const queueData = $input.first().json;
const tickets = queueData.tickets || [];
const now = new Date();
const SLA_MINUTES = 120;

const overdue = tickets.filter(t => {
  if (!t.createdAt) return false;
  const created = new Date(t.createdAt);
  const ageMinutes = (now - created) / (1000 * 60);
  return ageMinutes > SLA_MINUTES;
});

if (overdue.length === 0) {
  return [];
}

const rows = overdue.map(t =>
  `<tr><td style="padding:8px;border-bottom:1px solid #eee;">${t.ticketNumero || 'N/A'}</td><td style="padding:8px;border-bottom:1px solid #eee;">${t.clientNom || 'N/A'}</td><td style="padding:8px;border-bottom:1px solid #eee;">${t.canal || 'N/A'}</td><td style="padding:8px;border-bottom:1px solid #eee;color:#C62828;font-weight:700;">⚠️ ${Math.round((now - new Date(t.createdAt)) / 60000)} min</td></tr>`
).join('');

const html = `
<div style="font-family:'Segoe UI',Arial,sans-serif;max-width:600px;margin:0 auto;">
  <div style="background:linear-gradient(135deg,#B71C1C,#D32F2F);color:white;padding:25px;border-radius:12px 12px 0 0;text-align:center;">
    <h1 style="margin:0;">⚠️ Alerte SLA</h1>
    <p style="margin:5px 0 0;opacity:0.9;">${overdue.length} ticket(s) en attente depuis plus de ${SLA_MINUTES} min</p>
  </div>
  <div style="background:white;padding:25px;border:1px solid #e0e0e0;">
    <table style="width:100%;border-collapse:collapse;">
      <tr style="background:#FFEBEE;"><th style="padding:10px;text-align:left;">Numéro</th><th style="padding:10px;text-align:left;">Client</th><th style="padding:10px;text-align:left;">Canal</th><th style="padding:10px;text-align:left;">Attente</th></tr>
      ${rows}
    </table>
  </div>
  <div style="background:#f8f9fa;padding:15px;border-radius:0 0 12px 12px;text-align:center;color:#888;font-size:12px;">
    <p>© 2026 AutoAssist — Alerte automatique n8n</p>
  </div>
</div>`;

return [{ json: { html, subject: '⚠️ ALERTE SLA — ' + overdue.length + ' ticket(s) en dépassement', count: overdue.length } }];
